div.script:
(function () {
    var script = document.currentScript;
    var base = script && script.getAttribute('data-reload-base');
    if (!base) { return; }
    setTimeout(function () {
        // Cache-buster: cada reload usa querystring única para impedir o browser
        // de reaproveitar a resposta anterior do spinner (que retornaria 200
        // em vez do 303 atual do backend).
        var sep = base.indexOf('?') === -1 ? '?' : '&';
        window.location.replace(base + sep + '_=' + Date.now());
    }, 2000);
})();
